     let possibles = &arg.get_possible_values();
     let possibles: Vec<&clap::builder::PossibleValue> =
         possibles.iter().filter(|pos| !pos.is_hide_set()).collect();

     if !possibles.is_empty() {
         return Some(format_possible_values(&possibles));
