     let mut lines = vec![];
     for value in possibles {
         let mut roff = Roff::default();
         let val_name = value.get_name();
         match value.get_help() {
             Some(help) => {
                 roff.text([roman(format!("{val_name}: {help}"))]);
             }
             None => {
                 roff.text([roman(val_name.to_owned())]);
             }
         }
         lines.push(roff);
     }
     lines
